// Card NEW-20261022-ORQ-uno-no-jogo: the Quadradão 1.0 (Uno) of the chaveiro objective, 8 views generated by the Codex
// (evidence NEW-20261021-ORQ-uno-8-lados/t2/quadradao-8dir.png, green background, views S,SO,O,NO / N,NE,L,SE).
// Keys the green out (no fringe), cuts each view by its empty columns, puts the 8 on one 4×2 sheet of square cells at
// one scale, the lowest point (the wheels) on the 85 % line and the box centred. Prints each view's opaque width/height.
// usage: node scripts/import-uno.mjs <quadradao-8dir.png> [out=public/art/lite/veiculos/quadradao.webp] [cell=320]
import sharp from 'sharp';
import {mkdirSync} from 'node:fs';
import {dirname} from 'node:path';
const [IN,OUT='public/art/lite/veiculos/quadradao.webp',CELL='320']=process.argv.slice(2);const C=+CELL;
if(!IN)throw new Error('usage: node scripts/import-uno.mjs <quadradao-8dir.png> [out] [cell]');
const {data,info}=await sharp(IN).ensureAlpha().raw().toBuffer({resolveWithObject:true});
for(let p=0;p<data.length;p+=4){const r=data[p],g=data[p+1],b=data[p+2],grn=g-Math.max(r,b);
  if(grn>110&&g>170)data[p+3]=0;
  // the anti-aliased edge: partial alpha, and the green spill taken off (no green fringe)
  else if(grn>30){data[p+3]=Math.min(data[p+3],Math.round(255*(1-(grn-30)/80)));data[p+1]=Math.max(r,b);}}
const W=info.width,H=info.height,ch=Math.floor(H/2);
const keyed=await sharp(Buffer.from(data),{raw:{width:W,height:H,channels:4}}).png().toBuffer();
const boxes=[];
for(let row=0;row<2;row++){const y0=row*ch,occ=new Array(W).fill(0);
  for(let y=0;y<ch;y++)for(let x=0;x<W;x++)if(data[((y0+y)*W+x)*4+3]>60)occ[x]++;
  const runs=[];let st=-1;for(let x=0;x<=W;x++){const on=x<W&&occ[x]>0;if(on&&st<0)st=x;if(!on&&st>=0){runs.push([st,x-1]);st=-1;}}
  const m=[];for(const r of runs){if(m.length&&r[0]-m[m.length-1][1]<12)m[m.length-1][1]=r[1];else m.push([...r]);}
  const big=m.sort((a,b)=>(b[1]-b[0])-(a[1]-a[0])).slice(0,4).sort((a,b)=>a[0]-b[0]);
  if(big.length<4)throw new Error(`row ${row}: found ${big.length} views`);
  for(const [l,r] of big){let t=ch,b=-1;for(let y=0;y<ch;y++)for(let x=l;x<=r;x++)if(data[((y0+y)*W+x)*4+3]>60){if(y<t)t=y;if(y>b)b=y;}
    boxes.push({y0,t,b,l,r});}}
const maxW=Math.max(...boxes.map(o=>o.r-o.l+1)),maxH=Math.max(...boxes.map(o=>o.b-o.t+1));
const scale=Math.min((C*.96)/maxW,(C*.8)/maxH),FOOT=Math.round(C*.85),comp=[],views=[];
const names=['S','SO','O','NO','N','NE','L','SE'];
for(const [k,o] of boxes.entries()){const w=o.r-o.l+1,h=o.b-o.t+1,sw=Math.round(w*scale),sh=Math.round(h*scale);
  const piece=await sharp(keyed).extract({left:o.l,top:o.y0+o.t,width:w,height:h}).resize(sw,sh,{kernel:'lanczos3'}).png().toBuffer();
  comp.push({input:piece,left:(k%4)*C+Math.round((C-sw)/2),top:Math.floor(k/4)*C+FOOT-sh});views.push({v:names[k],w:sw,h:sh});}
mkdirSync(dirname(OUT),{recursive:true});
await sharp({create:{width:4*C,height:2*C,channels:4,background:{r:0,g:0,b:0,alpha:0}}}).composite(comp).webp({quality:88,alphaQuality:100,effort:6}).toFile(OUT);
console.log(JSON.stringify({cell:C,foot:FOOT/C,views}));
